var a=`0814-seswaa`;var i=`world-0814`;var s=`BW`;var t=`southern-africa`;var o=4;var r=201;var h={en:`Seswaa`,ua:`Сесваа`};var d={en:`Seswaa is a Botswana dish made with beef chuck, yellow onion, bay leaf, parsley. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Сесваа, страва кухні країни Ботсвана. Основні складники: яловича лопатка, жовта цибуля, лавровий лист, петрушка. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var l=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`beef-chuck`,1250,`g`],[`yellow-onion`,200,`g`],[`table-salt`,7,`g`],[`black-peppercorn`,4,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 175 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 175 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:175,i:[[`water`,1e3,`ml`],[`bay-leaf`,2,`pcs`]]},{en:`Drain the cooked ingredients and pound or mash while warm for about 12 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 12 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:12,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,15,`g`]]}];var u={slug:a,id:i,country:`BW`,region:t,servings:4,minutes:201,title:h,text:d,steps:l};export{s as country,u as default,i as id,r as minutes,t as region,o as servings,a as slug,l as steps,d as text,h as title};